export const WRITTEN_ES: FaqEntry[] = [
  { id: 'ironSells', topic: 'La fundición y el mercado del hierro', words: ['fundicion vende', 'hierro vende', 'vende hierro', 'hierro automatico', 'hierro mercado', 'barras hierro', 'siderurgia vende'],
    answer: 'Sí, y sin condición: una fundición recién construida vacía al instante sus barras en el mercado del hierro, las casillas más caras primero, y cobras el precio impreso de cada una. No se pide ningún enlace ni ningún mercader. Si todas las barras se van así, la loseta se voltea en el acto. Lo que queda encima sirve después para las construcciones y los desarrollos de cualquiera.' },
  { id: 'coalSells', topic: 'La mina y el mercado del carbón', words: ['mina vende', 'carbon vende', 'vende carbon', 'mina automatica', 'carbon mercado', 'mina mercado'],
    answer: 'Solo si la mina alcanza un espacio de mercader por enlaces, tuyos o de otros. En ese caso, al construirla, todos los cubos que caben van al mercado del carbón y cobras su precio; si el último se va así, la loseta se voltea. Fuera del alcance de un mercader, la mina conserva sus cubos. Y esta venta solo ocurre al construir, nunca después.' },
  { id: 'flipMine', topic: 'Cuándo se voltea una mina', words: ['mina voltea', 'voltear mina', 'cuando voltea mina', 'fundicion voltea', 'cerveceria voltea', 'ultimo cubo'],
    answer: 'Una mina o una fundición se voltea cuando sale su último cubo, una cervecería cuando se bebe su último barril, y da igual quién los haya tomado. Voltearla avanza tu marcador de ingresos las casillas impresas en la loseta, y sus puntos quedan asegurados para el final de la era. Una mina vaciada por los demás es una mina pagada.' },
  { id: 'flipWorks', topic: 'Cuándo se voltea una obra', words: ['obra voltea', 'hilanderia voltea', 'algodon voltea', 'manufactura voltea', 'alfareria voltea', 'como voltear'],
    answer: 'Una hilandería, una manufactura o una alfarería solo se voltea con la acción Vender: hace falta un enlace hasta un mercader que compre esos bienes, y la cerveza que pida la loseta. Nada más la voltea, y una loseta nunca volteada no puntúa nada.' },
  { id: 'ironWhere', topic: 'Dónde encontrar hierro', words: ['donde hierro', 'encontrar hierro', 'encuentro hierro', 'consigo hierro', 'hierro enlace', 'hierro conectado'],
    answer: 'En cualquier parte: el hierro se toma de cualquier fundición sin voltear del tablero, sea de quien sea, sin noción de distancia ni de red. A falta de fundición, se compra en el mercado del hierro, también sin ninguna conexión. Es la gran diferencia con el carbón.' },
  { id: 'coalWhere', topic: 'Dónde encontrar carbón', words: ['donde carbon', 'encontrar carbon', 'encuentro carbon', 'consigo carbon', 'carbon enlace', 'carbon conectado'],
    answer: 'El carbón debe venir de una mina sin voltear conectada a tu obra por enlaces —la tuya o la de cualquiera, la más cercana primero—. A falta de ella, se compra en el mercado, pero solo si la obra alcanza un espacio de mercader. Si no, la construcción es imposible.' },
  { id: 'marketPrice', topic: 'El precio del carbón y del hierro', words: ['precio carbon', 'precio hierro', 'mercado sube', 'mercado repone', 'mercado vacio'],
    answer: 'Siempre se compra primero la casilla más barata, y el precio sube a medida que salen los cubos. Los mercados nunca se reponen solos: solo las minas y fundiciones nuevas, al vender sus cubos, los vuelven a llenar, de las casillas más caras a las más baratas. Con el mercado vacío se paga igualmente: 8 £ el carbón, 6 £ el hierro.' },
  { id: 'beer', topic: 'De dónde viene la cerveza', words: ['donde cerveza', 'encontrar cerveza', 'encuentro cerveza', 'consigo cerveza', 'cerveza vender', 'barril', 'cerveceria sirve'],
    answer: 'Tres fuentes, y cada barril puede venir de una distinta: tus propias cervecerías sin voltear, en cualquier parte del mapa y sin condición; la cervecería de un rival, pero solo si está conectada a la loseta vendida; o el barril junto al mercader al que vendes, que además da su bonificación. Sin la cerveza pedida, la acción Vender es imposible.' },
  { id: 'merchantBonus', topic: 'La bonificación del mercader', words: ['bonificacion mercader', 'barril mercader', 'bonus mercader'],
    answer: 'Beber el barril junto a una loseta de mercader da su bonificación: dinero, puntos, ingresos o un desarrollo gratis según el mercader. Hay un barril por loseta de mercader no blanca, así que algunos mercaderes llevan dos, y cada barril solo se bebe una vez por era. Los barriles se reponen al pasar a la era del ferrocarril.' },
  { id: 'sellHow', topic: 'Cómo vender', words: ['como vender', 'accion vender', 'vender varias', 'venta'],
    answer: 'Descarta una carta, la que sea, elige una de tus hilanderías, manufacturas o alfarerías sin voltear conectada a un mercader que compre esos bienes, y bebe la cerveza pedida. La loseta se voltea: los ingresos suben enseguida, los puntos esperan al final de la era. Una sola acción puede voltear varias losetas, tantas como cerveza puedas pagar.' },
  { id: 'buildCard', topic: 'Qué carta construye qué', words: ['que carta', 'carta lugar', 'carta industria', 'carta construye', 'comodin'],
    answer: 'Una carta de lugar construye cualquier industria en la ciudad que nombra, incluso fuera de tu red. Una carta de industria construye esa industria en una ciudad de tu red. Mientras no tengas ninguna loseta en el tablero, una carta de industria construye en cualquier parte. Un comodín de lugar vale por cualquier ciudad salvo las dos cervecerías de granja, un comodín de industria por cualquier industria.' },
  { id: 'network', topic: 'Qué es tu red', words: ['tu red', 'mi red', 'que es red', 'donde puedo construir'],
    answer: 'Tu red son los lugares donde tienes una loseta, más los lugares que tocan tus enlaces. Una carta de industria solo construye ahí. Una carta de lugar, en cambio, ignora la red: construye en su ciudad pase lo que pase.' },
  { id: 'linkCost', topic: 'Lo que cuesta un enlace', words: ['precio canal', 'coste canal', 'cuesta canal', 'precio ferrocarril', 'coste ferrocarril', 'cuesta ferrocarril', 'doble ferrocarril', 'dos ferrocarriles'],
    answer: 'Un canal cuesta 3 £ en la era del canal, y un solo enlace por acción. En la era del ferrocarril, un ferrocarril cuesta 5 £ y un carbón; se pueden tender dos en la misma acción por 15 £, un carbón cada uno y una cerveza, que debe venir de una cervecería y nunca del barril de un mercader. Cada ferrocarril debe alcanzar una fuente de carbón una vez colocado.' },
  { id: 'linkScore', topic: 'Lo que puntúa un enlace', words: ['enlace puntua', 'canal puntos', 'icono enlace', 'cuanto da canal'],
    answer: 'Al final de la era, cada enlace puntúa los iconos de enlace de las losetas presentes en los lugares que toca —todas las losetas, sean de quien sean, volteadas o no— y dos puntos por un espacio de mercader. Después el enlace sale del tablero. Por eso un enlace hacia una ciudad bien construida vale más que un enlace hacia el vacío.' },
  { id: 'loan', topic: 'El préstamo', words: ['prestamo', 'prestado', 'devolver prestamo', 'reembolsar'],
    answer: 'Descarta una carta y toma 30 £ en el acto. Tu marcador de ingresos retrocede 3 niveles, no 3 casillas, y se coloca en la casilla más alta del nuevo nivel. El préstamo se rechaza si te haría bajar del nivel −10. Nunca se devuelve: al principio de la partida es dinero que construye losetas, al final es una pérdida neta de puntos.' },
  { id: 'develop', topic: 'El desarrollo', words: ['desarrollar', 'desarrollo', 'bombilla', 'quitar loseta tapete'],
    answer: 'Descarta una carta y retira una o dos losetas de tu tapete, un hierro por loseta retirada. Cada loseta retirada debe ser la más baja que quede en su columna en el momento de retirarla. Las alfarerías I y III llevan una bombilla y nunca se desarrollan. Así se alcanzan los niveles fuertes sin malgastar una construcción en una loseta mediocre.' },
  { id: 'scout', topic: 'Explorar', words: ['explorar', 'exploracion', 'scout', 'dos comodines'],
    answer: 'Descarta tres cartas en total y toma un comodín de lugar y un comodín de industria. Está prohibido si ya tienes un comodín en la mano. Una mano que no permite nada vale ese gasto; si no, tres cartas por dos es caro.' },
  { id: 'income', topic: 'Los ingresos', words: ['ingresos', 'pista ingresos', 'nivel ingresos', 'casilla nivel', 'cobro'],
    answer: 'La pista de ingresos cuenta casillas, y las casillas se agrupan en niveles: lo que paga es el nivel. Voltear una loseta avanza el marcador las casillas impresas en ella; un préstamo lo hace retroceder niveles enteros. Al final de cada ronda, cada uno cobra su nivel en libras, y lo paga al banco si el nivel es negativo.' },
  { id: 'order', topic: 'El orden de turno', words: ['orden turno', 'quien juega primero', 'gasto orden', 'primer jugador'],
    answer: 'Al final de cada ronda, el orden de la siguiente se decide por el dinero gastado: quien menos gastó juega primero. Con el mismo gasto, se mantiene el orden de la ronda anterior. Gastar poco compra, pues, la primera elección de espacios en la ronda siguiente.' },
  { id: 'actions', topic: 'El número de acciones', words: ['cuantas acciones', 'dos acciones', 'primera ronda accion', 'una accion'],
    answer: 'Dos acciones por turno, y cada acción cuesta una carta descartada, préstamo y pasar incluidos. Única excepción: en la primera ronda de la era del canal, una sola acción cada uno. Al final de la era, una mano reducida limita de forma natural el número de acciones.' },
  { id: 'hand', topic: 'La mano y el mazo', words: ['mano ocho', 'cuantas cartas', 'mazo', 'robar cartas', 'mazo vacio'],
    answer: 'Ocho cartas en la mano, que se completan después de cada turno mientras el mazo tenga. Cuando el mazo está vacío, la mano mengua una carta por acción y ya no se completa. La era termina cuando el mazo y todas las manos están vacíos: diez rondas con dos jugadores, nueve con tres, ocho con cuatro.' },
  { id: 'eraEnd', topic: 'El final de una era', words: ['final era', 'final canal', 'barrido', 'nivel 1 desaparece', 'recuento', 'entre las eras', 'entre eras', 'pasa entre'],
    answer: 'Primero se puntúan los enlaces, después las losetas volteadas; las losetas nunca volteadas no puntúan nada. Luego los enlaces salen del tablero. Solo al final de la era del canal, todas las losetas de nivel 1 salen también del tablero, volteadas o no. Los barriles de los mercaderes se reponen, los descartes se barajan de nuevo y cada uno roba ocho cartas.' },
  { id: 'scoring', topic: 'Cómo se ganan puntos', words: ['como ganar puntos', 'puntos victoria', 'dinero puntos', 'puntuacion final'],
    answer: 'Dos fuentes, contadas al final de cada era: los puntos impresos en tus losetas volteadas, y los iconos de enlace de los lugares que tocan tus enlaces. El dinero en caja no vale nada al final de una partida completa: solo es el medio. En caso de empate, desempatan los ingresos más altos, y después el dinero que quede.' },
  { id: 'railBeer', topic: 'Las cervecerías en la era del ferrocarril', words: ['cerveceria dos barriles', 'barril era ferrocarril', 'cerveceria ferrocarril'],
    answer: 'Una cervecería construida en la era del canal recibe un barril; construida en la era del ferrocarril, recibe dos. Es la misma loseta: decide la era en que se construye.' },
  { id: 'farmBrewery', topic: 'Las cervecerías de granja', words: ['cerveceria granja', 'farm brewery', 'fuera ciudad'],
    answer: 'Dos espacios de cervecería están fuera de las ciudades, en el mapa. Se construyen como los demás, pero ninguna carta de lugar los nombra y el comodín de lugar se rechaza allí: solo una carta de industria cervecería o un comodín de industria llegan a ellos, y el lugar debe estar en tu red, salvo si todavía no tienes nada en el tablero.' },
  { id: 'deckSize', topic: 'Composición del mazo', words: ['composicion mazo', 'cuantas cartas mazo', 'tamano mazo', 'cartas retiradas jugadores'],
    answer: 'El mazo solo contiene cartas de lugar y de industria: 40 cartas con 2 jugadores, 54 con 3 y 64 con 4. Con 2 jugadores, las ciudades azules y turquesas salen del mazo (Leek, Stoke, Stone, Uttoxeter, Belper, Derby); con 3 jugadores solo faltan Belper, Derby y una carta de Uttoxeter. En cuanto a las industrias, el carbón pasa de 2 a 3 cartas, la cerámica de 2 a 3, la carta doble algodón/manufactura de 0 a 6 y luego a 8, mientras que el hierro se queda en 4 y la cervecería en 5. Los 4 comodines de lugar y los 4 comodines de industria van aparte, en dos montones boca arriba, y nunca se mezclan con el mazo.' },
  { id: 'faceDownCard', topic: 'La carta boca abajo de la preparación', words: ['carta boca abajo', 'novena carta', 'carta oculta descarte'],
    answer: 'En la preparación recibes 8 cartas en la mano más 1 carta robada boca abajo que abre tu descarte: no se puede jugar. Al final de la era del canal, el motor baraja el mazo restante, todos los descartes —esa carta incluida— y las manos para formar el mazo de la era del ferrocarril. Después reparte 8 cartas y una nueva carta boca abajo a cada uno; esa ya no volverá al juego, porque la partida termina con la era del ferrocarril.' },
  { id: 'wildDiscard', topic: 'Comodín descartado', words: ['comodin descartado', 'comodin vuelve monton', 'tirar comodin'],
    answer: 'Un comodín jugado no va al descarte: el motor lo devuelve a su montón de comodines, donde una futura exploración podrá recuperarlo. Por eso los comodines nunca entran en el mazo de la era del ferrocarril, a diferencia de las cartas de lugar y de industria.' },
  { id: 'scoutWithWild', topic: 'Explorar con un comodín en la mano', words: ['explorar comodin mano', 'explorar con comodin', 'ya tengo comodin'],
    answer: 'No: la acción Explorar se rechaza si ya tienes un comodín, de lugar o de industria. Además necesitas al menos 3 cartas en la mano, porque la acción descarta 3, y que quede al menos un comodín en cada uno de los dos montones.' },
  { id: 'firstBuildAnywhere', topic: 'Construir sin nada en el tablero', words: ['ninguna loseta tablero', 'sin red construir', 'nada en tablero', 'primera loseta colocar'],
    answer: 'Sí. Mientras no tengas ni loseta ni enlace en el tablero, el motor considera que todo lugar forma parte de tu red: una carta de industria construye esa industria en cualquier parte del mapa, y cualquier carta coloca un enlace en cualquier ruta libre de la era. En cuanto colocas tu primera loseta o tu primer enlace, la condición de red vuelve.' },
  { id: 'locationCardTown', topic: 'Carta de lugar fuera de su ciudad', words: ['carta lugar ciudad', 'lugar fuera ciudad', 'carta ciudad otra parte'],
    answer: 'No. Una carta de lugar solo construye en la ciudad impresa en ella —el motor rechaza cualquier otro espacio indicando que esa carta solo construye allí—, pero permite cualquier industria admitida por el espacio, aunque la ciudad esté fuera de tu red. Para construir en otra parte hace falta una carta de industria dentro de tu red, o un comodín de lugar.' },
  { id: 'merchantGoods', topic: 'Bienes que compran los mercaderes', words: ['mercader compra', 'mercaderes compran', 'bienes mercader', 'loseta todos bienes', 'que mercader acepta', 'mercader blanco'],
    answer: 'Cada mercader compra lo que muestran las losetas de mercader que le han tocado: algodón, manufactura, cerámica, o «todos los bienes», que acepta los tres a la vez. Una loseta en blanco no compra nada y no lleva barril. El lote depende del número de jugadores: con 2 jugadores es blanca, blanca, algodón, manufactura y todos los bienes, de modo que la cerámica solo puede venderse por la loseta «todos los bienes»; Warrington solo se abre con 3 jugadores y Nottingham con 4.' },
  { id: 'sellMany', topic: 'Varias ventas en una acción', words: ['vender varias losetas', 'varias ventas', 'vender dos losetas', 'industrias distintas venta'],
    answer: 'Sí: una sola carta descartada cubre tantas ventas como quieras en la misma acción, y las losetas pueden ser de industrias distintas y pasar por mercaderes distintos. Cada loseta debe estar conectada a su mercader y paga su propia cerveza —1 o 2 barriles según la loseta—, y cada una avanza tus ingresos al voltearse.' },
  { id: 'doubleRailBarrel', topic: 'Barril de mercader y doble ferrocarril', words: ['barril mercader ferrocarril', 'doble ferrocarril cerveza', 'cerveza doble enlace'],
    answer: 'No. Para el doble enlace de la era del ferrocarril, el motor solo ofrece cervecerías: la tuya, esté donde esté en el tablero, o la de un rival conectada al segundo enlace una vez colocado. El barril junto a una loseta de mercader solo se bebe durante una acción Vender, porque es él el que da la bonificación del mercader.' },
  { id: 'coalOrder', topic: 'Orden de consumo del carbón', words: ['orden carbon', 'consumo carbon', 'mina mas cercana', 'que carbon usa', 'carbon prioritario'],
    answer: 'El carbón viene primero de las minas sin voltear conectadas al lugar por enlaces, la más cercana primero en número de enlaces y sin importar el propietario, y es gratis. A igual distancia, el reglamento deja elegir al jugador; el motor, en cambio, se decide por la mina que tiene más cubos. Agotadas las minas conectadas, se compra en el mercado, pero solo si un espacio de mercader está conectado al lugar; si no, la construcción se rechaza por falta de carbón conectado.' },
  { id: 'ironConnection', topic: 'Conexión necesaria para el hierro', words: ['hierro conexion', 'hierro sin enlace', 'hierro distancia'],
    answer: 'Ninguna. El hierro se toma de cualquier fundición sin voltear del tablero, sea cual sea su propietario y sin ningún enlace, y a falta de ella en el mercado del hierro, también sin conexión. El motor te deja elegir la fundición que da el cubo, y solo pasa al mercado cuando ninguna fundición del tablero tiene ya un cubo que dar.' },
  { id: 'marketEmpty', topic: 'Mercado vacío', words: ['mercado vacio carbon', 'mercado vacio hierro', 'no quedan cubos mercado', 'precio mercado vacio'],
    answer: 'Un mercado vacío no impide comprar: cada cubo cuesta entonces 8 £ el carbón y 6 £ el hierro, sin límite de cantidad. Antes se paga casilla por casilla empezando por la más barata, de 1 a 7 £ el carbón y de 1 a 5 £ el hierro. Nada repone los mercados: solo la construcción de una mina o de una fundición vuelve a poner cubos.' },
  { id: 'marketFillTiming', topic: 'Cuándo van los cubos al mercado', words: ['cuando cubos mercado', 'llenar el mercado', 'cubos vendidos construccion', 'mercado se rellena'],
    answer: 'Solo en el momento de construir. Una fundición nueva siempre vierte sus cubos en el mercado del hierro; una mina nueva solo vierte en el mercado del carbón si está conectada a un espacio de mercader. Los cubos llenan primero las casillas más caras, cobras su valor impreso, y si la loseta se vacía por completo se voltea en el acto. Una vez colocada, la loseta nunca más venderá un cubo al mercado.' },
  { id: 'developLowest', topic: 'Elegir la loseta desarrollada', words: ['desarrollar loseta elegida', 'desarrollar nivel superior', 'que loseta desarrollar'],
    answer: 'No: el motor solo te ofrece la loseta de encima de cada pila, es decir, el nivel más bajo que queda de esa industria. Las alfarerías con bombilla, niveles I y III, nunca pueden retirarse con Desarrollar y el motor lo rechaza expresamente; solo una construcción las quita del tapete.' },
  { id: 'developTwoCost', topic: 'Desarrollar dos losetas', words: ['desarrollar dos losetas', 'dos losetas una carta', 'coste doble desarrollo'],
    answer: 'La carta es la misma: Desarrollar descarta una sola carta, retires una loseta o dos. Lo que se duplica es el hierro: 1 cubo por loseta retirada. Dos retiradas en la misma industria quitan la loseta de encima y luego la que está justo debajo, siempre que no lleve bombilla.' },
  { id: 'passCost', topic: 'Coste de pasar', words: ['pasar cuesta', 'pasar turno', 'pasar carta', 'pasar una accion'],
    answer: 'Pasar cuesta una carta por acción pasada, exactamente como cualquier otra acción: la carta va al descarte y no ocurre nada más. Si no eliges la carta, el motor descarta la primera de tu mano.' },
  { id: 'spendOrder', topic: 'Dinero gastado y orden de turno', words: ['dinero gastado orden', 'gasto orden turno', 'compras mercado orden', 'que cuenta gasto'],
    answer: 'Sí: cuenta todo lo que has pagado durante la ronda: el precio de las losetas, las 3 o 5 £ de los enlaces, las 15 £ del doble enlace, y el carbón y el hierro comprados en el mercado. El dinero cobrado no compensa nada: ni la venta de cubos al mercado al construir, ni el préstamo, ni los ingresos. Al final de la ronda, quien menos ha gastado juega primero; en caso de empate, se conserva el orden relativo anterior.' },
  { id: 'canalSecondLink', topic: 'Dos enlaces en la era del canal', words: ['dos enlaces canal', 'doble canal', 'segundo canal accion'],
    answer: 'No: en la era del canal, una acción Red coloca exactamente un enlace, por 3 £ y sin carbón. El doble enlace es una opción de la era del ferrocarril —15 £ en total, 1 carbón por enlace y 1 barril de cerveza tomado de una cervecería— y el motor rechaza cualquier intento en la era del canal.' },
  { id: 'refillEight', topic: 'Completar la mano', words: ['completar mano', 'robar despues turno', 'mano ocho cartas'],
    answer: 'Al final de tu turno robas hasta tener 8 cartas, nunca más. Cuando el mazo está vacío, la mano ya no se completa y mengua de una ronda a otra; un jugador sin cartas no juega turno, y la era termina cuando el mazo y todas las manos están vacíos.' },
  { id: 'wildBuildReach', topic: 'Alcance de los comodines', words: ['comodin lugar red', 'comodin industria red', 'comodin construir cualquier parte'],
    answer: 'Un comodín de lugar construye en la ciudad que elijas, incluso fuera de tu red, pero nunca en las dos cervecerías de granja, que solo aceptan cartas de industria. Un comodín de industria construye la industria que elijas, pero solo en un lugar de tu red, salvo si aún no tienes ni loseta ni enlace en el tablero, en cuyo caso todo el tablero está abierto.' },
  { id: 'cottonCard', topic: 'Carta de algodón o de manufactura', words: ['carta algodon sola', 'carta doble algodon', 'carta manufactura algodon'],
    answer: 'No existe carta de algodón sola ni carta de manufactura sola: las dos industrias comparten una carta doble que sirve para una u otra. El motor pone 8 en el mazo con 4 jugadores, 6 con 3 jugadores y ninguna con 2; con dos, una hilandería o una manufactura solo se construye con carta de lugar o con comodín.' },
  { id: 'wildPilesLeft', topic: 'Número de comodines en juego', words: ['cuantos comodines', 'monton comodines vacio', 'comodines disponibles'],
    answer: 'Hay 4 comodines de lugar y 4 comodines de industria, en dos montones boca arriba junto al mazo. Cada exploración retira uno de cada, cada comodín jugado vuelve a su montón, y la acción se rechaza en cuanto uno de los dos montones está vacío.' },
  { id: 'sellConnection', topic: 'Conexión necesaria para vender', words: ['vender conexion mercader', 'loseta conectada mercader', 'vender sin enlace'],
    answer: 'La loseta vendida debe estar unida al mercader por una cadena de enlaces de la era en curso, sean de quien sean, y ese mercader debe mostrar una loseta que compre esa industria. Sin camino, la loseta simplemente no aparece entre los destinos de venta. Solo se venden las hilanderías, manufacturas y alfarerías: las minas, fundiciones y cervecerías se voltean al vaciarse.' },
  { id: 'rivalBeer', topic: 'Cerveza de un rival para una venta', words: ['cerveza rival conectada', 'cerveceria rival venta', 'cerveza cerveceria rival'],
    answer: 'Para una venta, tus propias cervecerías sin voltear dan un barril estén donde estén en el tablero; las de un rival solo cuentan si la loseta vendida está conectada a ellas. El motor bebe primero el barril del mercader cuando queda uno, porque da la bonificación, luego tus cervecerías, luego las de los demás, pero puedes elegir tú mismo cada fuente.' },
  { id: 'developIronCost', topic: 'El hierro del desarrollo', words: ['hierro desarrollo coste', 'desarrollar pagar hierro', 'desarrollo mercado hierro'],
    answer: 'Desarrollar no cuesta dinero en sí: 1 carta y 1 cubo de hierro por loseta retirada. El hierro es gratis si viene de una fundición sin voltear del tablero, sea cual sea y sin condición de conexión; si no queda ninguna, se compra en el mercado del hierro y el motor rechaza la acción si no puedes pagar ese precio.' },
  { id: 'matColumn', topic: 'Qué loseta sale de la columna del tapete', words: ['loseta mas baja', 'loseta sale columna', 'columna tapete', 'nivel mas bajo', 'elegir loseta columna'],
    answer: 'Siempre construyes la loseta del nivel más bajo que queda en la columna de esa industria en tu tapete: nunca eliges un nivel más alto. Cada construcción retira esa loseta y descubre la siguiente, así que la columna sube de nivel a lo largo de la partida. La acción Desarrollar también retira una loseta por arriba de la columna, sin colocar nada en el tablero, lo que hace subir la columna sin construir.' },
  { id: 'cottonCost', topic: 'Coste de las hilanderías de algodón', words: ['hilanderia cuesta', 'precio hilanderia', 'coste hilanderia algodon', 'hilanderia nivel'],
    answer: 'Hilandería I: 12 £, sin carbón ni hierro; es la única hilandería que no consume nada. II: 14 £ y 1 carbón. III: 16 £ con 1 carbón y 1 hierro; IV: 18 £ con 1 carbón y 1 hierro. Los ingresos van de +5 a +2 casillas y los PV de 5 a 12 al subir de nivel; cada hilandería se vende por 1 barril de cerveza.' },
  { id: 'manufacturerCost', topic: 'Coste de las manufacturas y sus excepciones', words: ['manufactura cuesta', 'precio manufactura', 'manufactura dos cervezas', 'manufactura sin enlace'],
    answer: 'Manufactura I: 8 £ y 1 carbón; II: 10 £ y 1 hierro; III: 12 £ y 2 carbones; IV: 8 £ y 1 hierro. V: 16 £ y 1 carbón; VI: 20 £ sin ningún recurso; VII: 16 £ con 1 carbón y 1 hierro; VIII: 20 £ y 2 hierros. Dos excepciones que recordar: los niveles III y VII no tienen ningún icono de enlace y por tanto no dan nada a los enlaces vecinos, y el nivel V pide 2 barriles de cerveza para venderse. Todas las demás manufacturas se venden por 1 barril.' },
  { id: 'coalCubes', topic: 'Coste de la mina y cubos colocados', words: ['mina carbon cuesta', 'cuantos cubos mina', 'cubos mina carbon', 'precio mina'],
    answer: 'Mina I: 5 £, 2 cubos colocados; II: 7 £, 3 cubos; III: 8 £ con 1 hierro, 4 cubos; IV: 10 £ con 1 hierro, 5 cubos. Los cubos se colocan sobre la loseta al construirla y sirven después a cualquier jugador conectado a ella. Los ingresos son de +4, +7, +6 y +5 casillas, y los PV de 1, 2, 3 y 4.' },
  { id: 'ironBars', topic: 'Coste de la fundición y barras colocadas', words: ['fundicion cuesta', 'cuanto hierro fundicion', 'barras fundicion', 'precio fundicion'],
    answer: 'Fundición I: 5 £ y 1 carbón, 4 barras de hierro colocadas; II: 7 £ y 1 carbón, 4 barras; III: 9 £ y 1 carbón, 5 barras; IV: 12 £ y 1 carbón, 6 barras. Cada nivel consume exactamente 1 carbón al construirse, nunca hierro. Los ingresos son de +3, +3, +2 y +1 casillas, y los PV de 3, 5, 7 y 9.' },
  { id: 'potteryCost', topic: 'Coste de las alfarerías y losetas con bombilla', words: ['alfareria cuesta', 'precio alfareria', 'bombilla', 'ceramica cuesta'],
    answer: 'Alfarería I: 17 £ y 1 hierro, 10 PV; II: gratis pero 1 carbón, 1 PV; III: 22 £ y 2 carbones, 11 PV; IV: gratis con 1 carbón, 1 PV; V: 24 £ y 2 carbones, 20 PV. Los niveles I y III llevan la bombilla: no pueden retirarse con Desarrollar, solo la construcción los saca del tapete; la V, en cambio, sí se puede desarrollar. La alfarería I es la única loseta de nivel 1 del juego que también se construye en la era del ferrocarril, mientras que la V está reservada a la era del ferrocarril. La I y la III se venden por 1 y 2 barriles, la II y la IV por 1, la V por 2.' },
  { id: 'breweryBarrels', topic: 'Coste de la cervecería y barriles por era', words: ['cerveceria cuesta', 'cuantos barriles cerveceria', 'barriles cerveceria era', 'precio cerveceria'],
    answer: 'Cervecería I: 5 £ y 1 hierro; II: 7 £ y 1 hierro; III: 9 £ y 1 hierro; IV: 9 £ y 1 hierro, esta solo construible en la era del ferrocarril. El número de barriles no depende del nivel sino de la era: 1 barril en la era del canal, 2 barriles en la del ferrocarril, para todos los niveles; es lo que aplica el juego. Los ingresos son de +4 y luego +5 casillas, los PV de 4, 5, 7 y 9, y cada cervecería lleva 2 iconos de enlace.' },
  { id: 'flipRules', topic: 'Lo que voltea una loseta', words: ['loseta se voltea', 'cuando voltear loseta', 'por que loseta volteada', 'condicion voltear'],
    answer: 'Una mina o una fundición se voltea cuando sale su último cubo, una cervecería cuando se bebe su último barril, aunque sea un rival quien consuma el recurso. Una hilandería, una manufactura o una alfarería solo se voltea al venderse a un mercader conectado a ella. Una fundición, y una mina conectada a un espacio de mercader, se vacían hacia el mercado al construirse y se voltean en el acto si todo sale. Voltearse hace avanzar tus ingresos el número impreso y deja la loseta en condiciones de dar PV al final de la era.' },
  { id: 'tileIncomeNumber', topic: 'La cifra de ingresos impresa en la loseta', words: ['cifra ingresos loseta', 'ingresos impresos loseta', 'ingresos casillas niveles', 'avanzar marcador ingresos'],
    answer: 'La cifra de ingresos de una loseta es un número de casillas de la pista de progreso, no de niveles: una mina II volteada avanza tu marcador 7 casillas, no 7 niveles. La pista tiene 100 casillas y un nivel cuesta cada vez más casillas: 1 casilla por nivel hasta la casilla 10, luego 2 casillas hasta la 30, 3 hasta la 60 y 4 a partir de ahí. Solo el préstamo mueve el marcador en niveles, haciéndolo retroceder 3 niveles.' },
  { id: 'tileLinkIcon', topic: 'Los iconos de enlace de una loseta', words: ['icono enlace loseta', 'cifra enlace loseta', 'cuantos iconos enlace', 'iconos enlace tiene'],
    answer: 'El número de iconos de enlace de una loseta —0, 1 o 2— es el número de PV que da a cada enlace vecino en el recuento de final de era. Un enlace puntúa la suma de los iconos de enlace de todas las losetas colocadas en sus dos extremos, volteadas o no, y un espacio de mercader cuenta 2 de forma fija. Las manufacturas III y VII no tienen ningún icono; la hilandería II, las manufacturas I y V, la mina I y las cuatro cervecerías tienen 2, y todas las demás losetas tienen 1.' },
  { id: 'matEraIcon', topic: 'Los iconos de canal y de ferrocarril del tapete', words: ['icono canal tapete', 'icono ferrocarril loseta', 'construible era ferrocarril', 'loseta bloqueada era'],
    answer: 'El icono de canal a la izquierda de una loseta del tapete significa que solo puede construirse en la era del canal, el icono de ferrocarril que espera la era del ferrocarril, y la ausencia de icono que vale para las dos eras. Todas las losetas de nivel 1 llevan el icono de canal, salvo la alfarería I, que se construye en las dos eras; solo la alfarería V y la cervecería IV llevan el icono de ferrocarril. Una loseta de canal que siga en tu tapete en la era del ferrocarril ya solo puede salir con Desarrollar, y el juego rechaza la construcción diciendo que ese nivel no puede construirse en la era en curso.' },
  { id: 'tileSlotIcons', topic: 'Los iconos de un espacio de ciudad', words: ['espacio icono industria', 'donde poner loseta', 'espacio doble icono', 'espacio rechaza industria'],
    answer: 'Cada espacio de una ciudad muestra uno o varios iconos de industria y solo acepta esas industrias: una hilandería solo puede ir en un espacio con el icono de algodón. Un espacio con doble icono acepta una u otra de las dos industrias, y los clics sucesivos hacen pasar las opciones posibles. Si un espacio ya está ocupado por otra industria, el juego lo rechaza y lo dice; solo queda entonces sobreconstruir una loseta de la misma industria.' },
  { id: 'overbuildTile', topic: 'Sobreconstruir una loseta', words: ['sobreconstruir', 'sobre construir', 'reemplazar loseta rival', 'construir encima'],
    answer: 'Sobreconstruir es colocar una loseta sobre otra ya colocada de la misma industria y de un nivel estrictamente superior. Sobre tus propias losetas siempre está permitido, volteadas o no; sobre la loseta de un rival, solo las minas de carbón y las fundiciones pueden, y solo si no queda ningún cubo de ese recurso en ninguna parte: ni en una loseta del tablero ni en el mercado. En la era del canal, sobreconstruir es la única manera de volver a colocar una loseta en una ciudad donde ya tienes una, porque el espacio reemplazado no cuenta para el límite de una loseta por lugar.' },
  { id: 'oneTilePerPlace', topic: 'Una loseta por lugar en la era del canal', words: ['una loseta por lugar', 'dos losetas misma ciudad', 'limite era canal', 'varias losetas ciudad'],
    answer: 'En la era del canal solo puedes tener una loseta de industria por lugar: el juego rechaza una segunda loseta en una ciudad donde ya tienes una, aunque sea en un espacio libre. El límite desaparece en la era del ferrocarril, donde puedes ocupar varios espacios del mismo lugar. No se aplica a sobreconstruir tu propia loseta, puesto que entonces solo la reemplazas.' },
  { id: 'tileRemovedFate', topic: 'Destino de una loseta sobreconstruida o vendida por deudas', words: ['loseta sobreconstruida', 'loseta retirada tablero', 'deuda vende losetas', 'falta dinero losetas'],
    answer: 'Una loseta sobreconstruida sale definitivamente de la partida con los recursos que le quedaban y ya no da ningún PV de final de era; en cambio, los ingresos y los PV que ya te había dado siguen siendo tuyos. Si tu dinero es negativo en el momento del cobro, el juego liquida tus losetas empezando por las más baratas, cada una devolviendo la mitad de su coste de construcción redondeada hacia abajo, y esas losetas salen también del tablero. Lo que aún falte después de la liquidación se paga en puntos de victoria, un punto por libra.' },
  { id: 'matTileCounts', topic: 'Número de losetas del tapete', words: ['cuantas losetas tapete', 'numero losetas industria', 'cuantas hilanderias', 'no quedan losetas'],
    answer: 'Cada jugador dispone de 45 losetas de industria: 11 hilanderías, 11 manufacturas, 7 minas de carbón, 7 cervecerías, 5 alfarerías y 4 fundiciones. Están ordenadas en seis columnas, del nivel más bajo al más alto, y cada nivel existe en un número fijo de ejemplares: por ejemplo, 3 hilanderías I, 2 hilanderías II, y luego 3 y 3. Cuando una columna está vacía, esa industria ya no puede construirse y el juego responde que no quedan losetas de ese tipo.' },
  { id: 'tileVpNumber', topic: 'Los PV impresos en una loseta', words: ['puntos victoria loseta', 'pv impreso loseta', 'loseta sin voltear puntos', 'cuantos puntos loseta'],
    answer: 'La cifra de PV de una loseta solo se puntúa en el recuento de final de era, y solo si la loseta está volteada: una loseta sin voltear vale cero. Los premios más gordos son la alfarería V con 20 PV, la hilandería IV con 12 PV, y luego la manufactura VIII y la alfarería III con 11 PV; las minas valen de 1 a 4 PV y las alfarerías II y IV 1 PV. Una loseta volteada se queda en el tablero y vuelve a puntuar en el recuento de la era del ferrocarril, salvo si es de nivel 1: esas se retiran entre las dos eras.' },
  { id: 'sweepLevelOne', topic: 'Retirada de las losetas de nivel 1', words: ['losetas nivel 1', 'retirar nivel 1', 'barrido losetas', 'nivel 1 ferrocarril'],
    answer: 'Después del recuento de la era del canal, todas las losetas de nivel 1 salen del tablero, volteadas o no, y ya no dan nada después. Los enlaces de canal desaparecen al mismo tiempo, tras haber puntuado. Las losetas de nivel 2 o más se quedan en su sitio tal cual y contarán en el recuento final si están volteadas.' },
  { id: 'potteryFreeTiles', topic: 'Las alfarerías gratuitas', words: ['alfareria gratis', 'alfareria gratuita', 'alfareria cero libras'],
    answer: 'Las alfarerías II y IV no cuestan ninguna libra, solo 1 carbón: solo dan 1 PV y una sola casilla de ingresos. Se retiran con Desarrollar o se construyen a bajo precio para descubrir la alfarería III y luego la alfarería V, que valen 11 y 20 PV. Se venden como las demás alfarerías, por 1 barril de cerveza.' },
  { id: 'progressBands', topic: 'Tramos de la pista de progreso', words: ['pista progreso', 'tramos ingresos', 'casillas niveles', 'casilla nivel ingresos'],
    answer: 'La pista tiene 100 casillas, de 0 a 99, y cada casilla muestra el nivel de ingresos que paga. Las casillas 0 a 10 valen los niveles −10 a 0, una casilla por nivel; las casillas 11 a 30 valen los niveles 1 a 10, dos casillas por nivel; las casillas 31 a 60 valen los niveles 11 a 20, tres casillas por nivel; las casillas 61 a 96 valen los niveles 21 a 29, cuatro casillas por nivel. Las tres últimas casillas, 97 a 99, valen todas el nivel 30: el techo.' },
  { id: 'markersStart', topic: 'Salida de los marcadores', words: ['inicio marcador ingresos', 'marcador victoria inicio', 'donde empieza ingresos'],
    answer: 'Tu marcador de ingresos empieza en la casilla 10 de la pista de progreso, que muestra el nivel 0 £: tu primer cobro es, pues, nulo, ni ganancia ni pérdida. Tu marcador de puntos de victoria empieza en 0.' },
  { id: 'spacesVsLevels', topic: 'Casillas frente a niveles', words: ['diferencia casillas niveles', 'avanzar casillas', 'retroceder niveles', 'casillas o niveles'],
    answer: 'Una loseta que se voltea hace avanzar tu marcador un número de casillas; un préstamo, en cambio, te hace retroceder 3 niveles y vuelve a poner el marcador en la casilla más alta del nivel alcanzado. La diferencia importa: en lo alto de la pista, cuatro casillas solo valen un nivel, de modo que avanzar 4 casillas puede añadir solo una libra de ingresos, mientras que un préstamo siempre te cuesta tres libras de ingresos de golpe.' },
  { id: 'roundEndOrder', topic: 'Secuencia de final de ronda', words: ['orden final ronda', 'pasos final ronda', 'que pasa ronda'],
    answer: 'El juego recalcula primero el orden de turno: quien menos ha gastado durante la ronda jugará primero, quien más ha gastado el último, y en caso de empate se conserva el orden relativo; los contadores de gasto vuelven entonces a cero. Viene después el cobro: cada uno cobra sus ingresos, salvo en la última ronda de la partida. Por último, si el mazo y todas las manos están vacíos, la era termina y sigue el recuento; si no, empieza la ronda siguiente, con el primer jugador en cabeza y 2 acciones cada uno.' },
  { id: 'paydayShortfall', topic: 'Ingresos negativos y bolsa vacía', words: ['ingresos negativos', 'cobro negativo', 'no alcanza pagar ingresos'],
    answer: 'Por debajo del nivel 0, el cobro es negativo y eres tú quien paga al banco. Si tu bolsa no alcanza, el juego retira losetas de industria tuyas del tablero —nunca tus enlaces—, cada una devolviendo la mitad de su coste redondeada hacia abajo, hasta cubrir lo que falta, y el sobrante es tuyo; las losetas retiradas salen del juego. En la mesa, es el jugador quien elige sus losetas: aquí el motor sacrifica automáticamente las más baratas primero. Si aún falta dinero, pierdes 1 PV por cada libra que falte y tu bolsa vuelve a cero.' },
  { id: 'noTileSale', topic: 'Malvender una loseta por dinero', words: ['vender una loseta', 'revender loseta', 'malvender loseta'],
    answer: 'No: una loseta colocada solo se malvende durante el cobro, y solo para cubrir unos ingresos negativos que tu bolsa no puede pagar. Ninguna acción del juego permite revender una industria para rellenar tus arcas, y las losetas de enlace nunca se recuperan.' },
  { id: 'characterTileMoney', topic: 'Dinero puesto en la loseta de personaje', words: ['loseta personaje dinero', 'dinero gastado personaje', 'para que sirve personaje'],
    answer: 'El dinero que gastas durante la ronda se cuenta sobre tu loseta de personaje: solo sirve para medir tus gastos. Al final de la ronda, quien menos ha gastado juega primero y quien más ha gastado el último; después ese dinero vuelve al banco y los contadores vuelven a cero. Nunca lo recuperas: solo depende de él tu puesto en el orden de turno.' },
  { id: 'eraEndOrder', topic: 'Secuencia de final de era', words: ['orden final era', 'pasos final era', 'secuencia recuento era'],
    answer: 'Una era termina en cuanto el mazo y todas las manos están vacíos, al final de la ronda en curso y después del cobro. Sigue el recuento: cada enlace te da 1 PV por icono de enlace de los lugares que toca, cada loseta de industria volteada da los PV impresos abajo a la izquierda, y después todas las losetas de enlace salen del tablero. Al final de la era del canal, la pantalla de recuento va seguida del barrido —losetas de nivel 1 retiradas, cerveza de los mercaderes repuesta, cartas barajadas y repartidas de nuevo— antes de que empiece la era del ferrocarril.' },
  { id: 'linkVpDetail', topic: 'Cuenta exacta de los PV de un enlace', words: ['icono enlace', 'cuanto puntua enlace', 'enlace mercader puntos'],
    answer: 'Cada enlace tuyo da 1 PV por icono de enlace presente en las losetas colocadas en los dos lugares que une, sea quien sea el propietario de esas losetas. Una loseta de industria muestra 0, 1 o 2 iconos según su tipo y su nivel, y un espacio de mercader cuenta siempre 2. El enlace Kidderminster–Worcester toca además la cervecería de granja del sur, que no tiene icono y por tanto no añade nada.' },
  { id: 'unflippedVp', topic: 'Loseta sin voltear en el recuento', words: ['loseta sin voltear', 'no volteada puntua', 'loseta no volteada'],
    answer: 'Una loseta que sigue por su cara negra, sin voltear, no da ningún punto de victoria en el recuento. Solo las losetas volteadas cuentan sus PV impresos; el panel de recuento muestra aparte lo que darían tus losetas sin voltear si se vaciaran a tiempo.' },
  { id: 'reshuffleBetweenEras', topic: 'Cartas barajadas entre las eras', words: ['cartas barajadas', 'nuevo mazo era', 'reparto cartas era'],
    answer: 'Al pasar a la era del ferrocarril vuelven todas las cartas: los descartes, las cartas boca abajo del principio y lo que quedaba en la mano se barajan en un mazo nuevo: 64 cartas con cuatro jugadores, 54 con tres, 40 con dos. Cada uno recibe entonces 8 cartas en la mano más 1 carta boca abajo que abre su descarte, exactamente como en la preparación. Los dos montones de comodines, de lugar y de industria, se quedan aparte y nunca se mezclan con el mazo.' },
  { id: 'gameEndTie', topic: 'Final de la partida y empate', words: ['empate ganador', 'desempate', 'mismos puntos'],
    answer: 'La partida termina al final de la última ronda de la era del ferrocarril, una vez hecho el recuento de esa era; esa ronda no tiene cobro. Gana quien tiene más PV; en caso de empate, se compara el nivel de ingresos, y después el dinero que quede. Si todo sigue igual, el motor designa de todos modos un solo ganador, el primero en el orden de los asientos, donde el reglamento declararía una victoria compartida.' },
  { id: 'initiationBonus', topic: 'Variante partida de iniciación', words: ['partida iniciacion', 'variante partida iniciacion', 'bonificacion iniciacion', 'solo era canal'],
    answer: 'La partida de iniciación termina al final de la era del canal: no hay era del ferrocarril, y la última ronda no tiene cobro. Tras el recuento normal de la era, cada uno suma +1 PV por cada 4 £ en caja, con un máximo de 15 PV, más tantos PV como su nivel de ingresos; un nivel negativo resta puntos. Por último, cada uno vuelve a contar los PV de sus losetas de industria volteadas de nivel 2 o más, y se designa al ganador.' },
  { id: 'roundsPerEra', topic: 'Número de rondas por era', words: ['cuantas rondas', 'numero rondas era', 'rondas dura era', 'duracion era'],
    answer: 'Cada era dura 10 rondas con dos jugadores, 9 con tres y 8 con cuatro; la barra superior muestra la ronda en curso y ese total. Este número se deriva del mazo —40, 54 o 64 cartas—, puesto que la era termina exactamente cuando el mazo y todas las manos están vacíos. La primera ronda de la era del canal solo da una acción; todas las demás dan dos.' },
  { id: 'startingPurse', topic: 'Dotación inicial', words: ['dinero inicial', 'cuanto dinero inicio', 'dinero empiezo', 'dinero principio', 'cartas iniciales'],
    answer: 'Empiezas la partida con 17 £ y 8 cartas en la mano, más 1 carta boca abajo que abre tu descarte. Tus marcadores están en 0 PV y en la casilla 10 de la pista de progreso, es decir, unos ingresos de 0 £. Tu tapete lleva 45 losetas de industria ordenadas por tipo y por nivel, de la más baja a la más alta.' },
  { id: 'incomeCeiling', topic: 'Techo y suelo de los ingresos', words: ['ingresos maximos', 'techo ingresos', 'ingresos minimos'],
    answer: 'Los ingresos tienen su techo en el nivel 30: las casillas 97 a 99 pagan todas 30 £ y el marcador no va más allá. Hacia abajo, no baja de la casilla 0, es decir −10 £; un préstamo que te haría pasar por debajo de ese nivel lo rechaza el juego, que te dice que los ingresos no pueden bajar más.' },
  { id: 'lastRoundNoPayday', topic: 'Sin cobro en la última ronda', words: ['ultima ronda ingresos', 'sin cobro ultima', 'cobro ultima ronda'],
    answer: 'El juego se salta el cobro de la última ronda de la partida: la última ronda de la era del ferrocarril, o la última ronda de la era del canal en una partida de iniciación. Todos los demás finales de ronda pagan con normalidad, incluida la última ronda de la era del canal en una partida completa.' },
  { id: 'merchantRearmEra', topic: 'Reposición de los mercaderes entre las eras', words: ['barriles mercaderes era', 'mercaderes repuestos', 'cerveza mercader vuelve'],
    answer: 'Al pasar a la era del ferrocarril, cada espacio de mercader recupera un barril de cerveza por loseta de mercader no blanca, y las bonificaciones de mercader ya tomadas vuelven a estar disponibles. Las cervecerías de los jugadores, en cambio, solo conservan los barriles que les quedan: nada las repone.' },
  { id: 'emptyDeckPlay', topic: 'Cuando el mazo está vacío', words: ['mazo vacio', 'no quedan cartas robar', 'mazo agotado'],
    answer: 'Cuando el mazo está vacío, ya no se completa la mano: cada uno juega las cartas que le quedan, dos por ronda. Un jugador que ya no tiene cartas simplemente se salta, y la era termina al final de la ronda en que el mazo y todas las manos están vacíos.' },
  { id: 'keepMoneyBetweenEras', topic: 'Lo que sobrevive al cambio de era', words: ['conservar dinero era', 'dinero entre eras', 'ingresos entre eras'],
    answer: 'Tu dinero, tu nivel de ingresos, tus puntos de victoria y tus préstamos pasan tal cual de la era del canal a la del ferrocarril: nada se pone a cero. Solo cambian las cartas, barajadas y repartidas de nuevo, las losetas de nivel 1, retiradas del tablero, y los enlaces, todos retirados en el recuento.' },
  { id: 'boardTowns', topic: 'Las ciudades y los espacios de industria', words: ['cuantas ciudades', 'numero ciudades', 'espacio industria', 'casillas industria', 'veinte ciudades'],
    answer: 'El tablero tiene 20 ciudades donde construir, 2 cervecerías de granja fuera de las ciudades y 5 espacios de mercader en el borde del mapa. Las 20 ciudades suman 47 espacios de industria: un espacio es una casilla impresa que nunca recibe más que una loseta, y los iconos dibujados en ella dicen qué industrias se admiten. Cada cervecería de granja solo ofrece un espacio, reservado a la cervecería.' },
  { id: 'biggestTowns', topic: 'Las ciudades de tres o cuatro espacios', words: ['cuatro espacios', 'tres espacios', 'birmingham espacios', 'ciudad mas grande'],
    answer: 'Birmingham es la única ciudad con cuatro espacios: algodón o manufactura, manufactura, fundición, manufactura. Cinco ciudades tienen tres: Coventry, Coalbrookdale, Stoke-on-Trent, Belper y Derby. Las otras catorce tienen dos.' },
  { id: 'doubleIconSlot', topic: 'Un espacio con dos iconos', words: ['doble icono', 'dos iconos', 'dos industrias espacio', 'espacio mixto'],
    answer: 'Un espacio que muestra dos iconos acepta una u otra de esas dos industrias, a elección de quien construye, nunca las dos: una vez colocada la loseta, el espacio está ocupado. Así, la casilla de alfarería o fundición de Stoke-on-Trent será una u otra según quién llegue primero. En el tablero, hacer clic en el espacio alterna entre las dos industrias propuestas.' },
  { id: 'slotIconsMeaning', topic: 'Los pequeños iconos de un espacio', words: ['pequenos iconos', 'que significan iconos', 'simbolos espacio', 'icono espacio vacio'],
    answer: 'En un espacio vacío, los iconos nombran las industrias admitidas: hilandería de algodón, manufactura, mina de carbón, fundición, alfarería, cervecería. Una vez colocada la loseta, los iconos que ves son los suyos: su nivel, los cubos de carbón o de hierro y los barriles de cerveza que lleva, y sus iconos de enlace —0, 1 o 2 según la loseta—, que dan un punto a cada enlace vecino al final de la era.' },
  { id: 'merchantPlaces', topic: 'Los espacios de mercader', words: ['espacios mercader', 'cuantos mercaderes', 'shrewsbury', 'nottingham', 'warrington'],
    answer: 'Cinco mercaderes bordean el mapa: Shrewsbury (1 casilla de loseta), Warrington, Nottingham, Oxford y Gloucester (2 casillas cada uno). Shrewsbury, Oxford y Gloucester sirven desde 2 jugadores, Warrington se abre con 3 jugadores y Nottingham con 4: es decir, 5 losetas de mercader repartidas con 2 jugadores, 7 con 3 y 9 con 4. Sus bonificaciones de cerveza: Shrewsbury +4 PV, Nottingham +3 PV, Warrington 5 £, Oxford +2 casillas de ingresos, Gloucester un desarrollo gratis.' },
  { id: 'merchantTileVsPlace', topic: 'Loseta de mercader y espacio de mercader', words: ['loseta mercader blanca', 'mercader en blanco', 'diferencia loseta mercader'],
    answer: 'El espacio de mercader es el lugar impreso en el borde del mapa; las losetas de mercader se sortean en la preparación y se colocan en sus casillas, y son ellas las que dicen lo que compra. Una loseta en blanco no compra nada y no tiene barril al lado: un mercader cuyas losetas sean todas blancas nunca te comprará nada en toda la partida. El juego mezcla las nueve losetas oficiales según la variante S4: 2 en blanco, 2 de algodón, 2 de manufactura, 2 de «todos los bienes» y 1 de alfarería.' },
  { id: 'allGoodsMerchant', topic: 'La loseta «todos los bienes»', words: ['todos bienes', 'todos los bienes', 'mercader compra todo'],
    answer: 'Una loseta «todos los bienes» acepta tres mercancías: el algodón, los productos manufacturados y la cerámica. Vale, pues, como los tres iconos juntos para una acción Vender. Las demás losetas solo compran la mercancía dibujada en ellas.' },
  { id: 'merchantCoalIcon', topic: 'El mercader y el mercado del carbón', words: ['conexion mercado carbon', 'mercader mercado carbon', 'comprar carbon mercader'],
    answer: 'Cada espacio de mercader lleva el icono de conexión al mercado del carbón: para comprar carbón en el mercado, el lugar donde construyes debe estar unido por enlaces a uno de los cinco mercaderes. El juego acepta cualquiera de los cinco, incluso el que no ha recibido ninguna loseta con 2 o 3 jugadores. El hierro, en cambio, no pide ninguna conexión.' },
  { id: 'farmBreweryCards', topic: 'Construir en una cervecería de granja', words: ['comodin lugar granja', 'carta granja cerveceria', 'construir en la granja'],
    answer: 'Las dos cervecerías de granja están fuera de las ciudades y solo aceptan una carta de industria cervecería o un comodín de industria; el juego rechaza expresamente el comodín de lugar, y ninguna carta de lugar del mazo las nombra. Como toda carta de industria, exige que el lugar esté en tu red, salvo si aún no tienes nada en el tablero. La cervecería que se instala allí recibe 1 barril en la era del canal y 2 en la del ferrocarril, como en cualquier otra parte.' },
  { id: 'farmBreweryLinks', topic: 'Conectar las cervecerías de granja', words: ['granja norte', 'granja sur', 'conectar la granja', 'cannock granja'],
    answer: 'La granja del norte, entre Cannock y Walsall, cuelga de una sola ruta: Cannock ↔ granja, practicable en las dos eras. La granja del sur no tiene ruta propia: el enlace Kidderminster ↔ Worcester une de una vez Kidderminster, Worcester y la granja, y no cabe allí ninguna segunda loseta. Ese enlace cuenta, pues, tres lugares para tu red y para el recuento de final de era.' },
  { id: 'whatIsALink', topic: 'Qué es un enlace', words: ['enlace une', 'enlace pertenece', 'pertenece a una ciudad', 'propietario enlace'],
    answer: 'Un enlace es una loseta colocada sobre una ruta impresa entre dos lugares: dos ciudades, o una ciudad y un mercader. Pertenece al jugador que lo ha colocado, nunca a una ciudad: no es una industria y no ocupa ningún espacio de industria. Pone sus dos extremos en tu red y después, al final de la era, puntúa los iconos de enlace de los lugares que toca antes de salir del tablero.' },
  { id: 'linkToMerchant', topic: 'Un enlace hacia un mercader', words: ['enlace hacia mercader', 'conectar un mercader', 'ruta mercader'],
    answer: 'Sí: siete rutas terminan en un mercader: Coalbrookdale ↔ Shrewsbury, Stoke-on-Trent ↔ Warrington, Derby ↔ Nottingham, Birmingham ↔ Oxford, Redditch ↔ Oxford, Worcester ↔ Gloucester y Redditch ↔ Gloucester. Un enlace así pone al mercader en tu red y abre la conexión al mercado del carbón. Al final de la era, un espacio de mercader cuenta siempre 2 iconos de enlace, tenga losetas o no.' },
  { id: 'canalOnlyRoute', topic: 'La ruta reservada al canal', words: ['canal solamente', 'ruta solo canal', 'burton walsall'],
    answer: 'Una sola ruta existe únicamente en la era del canal: Burton-on-Trent ↔ Walsall. Desaparece de las rutas disponibles en la era del ferrocarril, en la que no se puede colocar ningún ferrocarril allí. La era del canal ofrece, pues, 31 rutas: las 30 rutas comunes más esa.' },
  { id: 'railOnlyRoutes', topic: 'Las rutas reservadas al ferrocarril', words: ['ferrocarril solamente', 'ruta solo ferrocarril', 'ocho rutas ferrocarril'],
    answer: 'Ocho rutas solo existen en la era del ferrocarril: Belper ↔ Leek, Birmingham ↔ Nuneaton, Birmingham ↔ Redditch, Burton-on-Trent ↔ Cannock, Coventry ↔ Nuneaton, Derby ↔ Uttoxeter, Stone ↔ Uttoxeter y Tamworth ↔ Walsall. No se puede colocar ningún canal en ellas. La era del ferrocarril tiene, pues, 38 rutas: las 30 comunes más esas ocho.' },
  { id: 'oneLinkPerRoute', topic: 'Dos jugadores en la misma ruta', words: ['misma ruta', 'dos jugadores misma', 'duplicar un enlace'],
    answer: 'No: una ruta solo lleva una loseta de enlace en toda la era, y el juego quita de los destinos propuestos cualquier ruta ya ocupada. Nunca se duplica un enlace, y un ferrocarril no reemplaza a un canal. Todas las losetas de enlace salen del tablero después del recuento de la era del canal, lo que deja las rutas libres de nuevo para la era del ferrocarril.' },
  { id: 'whereToLayLink', topic: 'Dónde colocar un enlace', words: ['donde poner enlace', 'donde construir un enlace', 'primer enlace'],
    answer: 'Un enlace debe tocar tu red: un lugar donde tienes una loseta, o un extremo de uno de tus enlaces. Mientras no tengas nada en el tablero, puedes colocarlo en cualquier parte. Se coloca en una ruta libre de la era en curso: canal por 3 £, ferrocarril por 5 £ y un carbón que debe ser accesible una vez colocada la loseta.' },
  { id: 'connectedMeaning', topic: 'Lo que quiere decir «conectado»', words: ['conectado quiere decir', 'estar conectado', 'distancia en enlaces', 'contar los enlaces'],
    answer: 'Estar conectado es estar unido por una cadena de losetas de enlace colocadas en el tablero, sea quien sea su propietario: cuentan los enlaces de todos los jugadores. La distancia se cuenta en losetas de enlace atravesadas: el juego sirve el carbón primero desde la mina conectada más cercana, y desempata las distancias iguales por la mayor reserva. Es distinto de tu red, que solo sirve para decir dónde tienes derecho a construir y a colocar enlaces.' },
  { id: 'rivalMineLinks', topic: 'Servirse de la mina de un rival', words: ['mina rival', 'mina otro jugador', 'mis propios enlaces'],
    answer: 'Tus propios enlaces no son necesarios: para sacar carbón de una mina, basta con que una cadena de enlaces —colocados por cualquiera— una tu lugar con esa mina. El carbón sale de la mina conectada más cercana, y su propietario no tiene nada que decir; solo gana el volteo de su loseta cuando se va el último cubo. El hierro, en cambio, se toma de cualquier fundición del tablero, sin ningún enlace.' },
  { id: 'potteryPlaces', topic: 'Dónde se construyen las alfarerías', words: ['ciudades alfareria', 'donde alfareria', 'espacio alfareria', 'donde ceramica'],
    answer: 'Solo existen cuatro espacios de alfarería en el tablero: Belper, Stafford, Coventry, y Stoke-on-Trent, donde la casilla se comparte con la fundición. Sin embargo, cada jugador dispone de 5 losetas de alfarería: faltan sitios antes que losetas. Las cartas de lugar de Belper y Derby solo entran en el mazo con 4 jugadores.' },
  { id: 'linkTileStock', topic: 'El número de losetas de enlace', words: ['reserva enlaces', 'quedarse sin enlaces', 'numero losetas enlace', 'no quedan enlaces'],
    answer: 'El reglamento da 14 losetas de enlace por jugador, pero el juego no lleva ninguna reserva: nada te impide colocar más. Los únicos límites aplicados son las rutas aún libres de la era en curso, tu dinero, el carbón que exige un ferrocarril y la obligación de tocar tu red.' },
  { id: 'linksSweptAtEraEnd', topic: 'Los enlaces al final de la era', words: ['enlaces retirados', 'canales retirados', 'enlaces final era'],
    answer: 'Al final de cada era, cada enlace puntúa primero los iconos de enlace de los lugares que toca —cuentan las losetas de todos, volteadas o no, y un mercader vale 2— y después todas las losetas de enlace salen del tablero. La era del ferrocarril empieza, pues, con un mapa sin ningún enlace, y las redes hay que reconstruirlas. Las losetas de industria de nivel 1, por su parte, se retiran al pasar a la era del ferrocarril.' },
];
